export function StageRail({ stage }: { stage: Stage }) {
  const current = STAGES.findIndex((item) => item.id === stage);

  return (
    <ol className="grid grid-cols-4">
      {STAGES.map((item, index) => {
        const done = index < current;
        const active = index === current;
        return (
