                  <span className="shrink-0">
                    <Chip tone="wire">uploaded</Chip>
                  </span>
                )}
                <svg
                  aria-hidden
                  width="16"
                  height="16"
                  viewBox="0 0 16 16"
                  fill="none"
                  className="shrink-0 text-rule transition-colors group-hover:text-wire"
