const AUDIT = () => {
  const scrollable = (el) => {
    for (let n = el.parentElement; n; n = n.parentElement) {
      if (['auto', 'scroll', 'hidden'].includes(getComputedStyle(n).overflowX)) return true;
    }
    return false;
  };
  const doc = document.documentElement;
  const clipped = [], outside = [];
  const vw = window.innerWidth;
  for (const el of document.querySelectorAll('body *')) {
    const s = getComputedStyle(el);
    const own = ['auto', 'scroll', 'hidden'].includes(s.overflowX);
    const hidden = el.clientWidth <= 2 || el.clientHeight <= 2;
    if (!own && !hidden && el.scrollWidth - el.clientWidth > 1)
      clipped.push({ tag: el.tagName, cls: String(el.className).slice(0, 50), sw: el.scrollWidth, cw: el.clientWidth });
    const r = el.getBoundingClientRect();
    if (r.width > 0 && (r.right > vw + 1 || r.left < -1) && !scrollable(el))
      outside.push({ tag: el.tagName, cls: String(el.className).slice(0, 50), left: Math.round(r.left), right: Math.round(r.right) });
  }
  return { pageOverflow: doc.scrollWidth - doc.clientWidth, clipped: clipped.slice(0, 6), outside: outside.slice(0, 6) };
};

